css:
.hqr-page { page-break-after: always; display: flex; flex-wrap: wrap; align-content: flex-start; }
.hqr-page:last-child { page-break-after: auto; }
.hqr-card {
    box-sizing: border-box;
    width: 50%; height: 135mm;
    padding: 4mm;
    page-break-inside: avoid; break-inside: avoid;
}
.hqr-card > * { box-sizing: border-box; }
.hqr-top {
    background: #f3e7d3;
    border-radius: 3mm 3mm 0 0;
    height: 24mm; padding: 4mm 6mm;
    display: flex; align-items: center; justify-content: center;
}
.hqr-logo { max-height: 17mm; max-width: 100%; object-fit: contain; }
.hqr-estate { font-size: 12pt; font-weight: 800; color: #4e342e; letter-spacing: 0.5pt; }
.hqr-body {
    height: calc(127mm - 24mm);
    background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A//www.w3.org/2000/svg%27%20width%3D%2746%27%20height%3D%2746%27%3E%3Cg%20fill%3D%27none%27%20stroke%3D%27rgba%28240%2C201%2C138%2C0.055%29%27%20stroke-width%3D%271.2%27%3E%3Cellipse%20cx%3D%2713%27%20cy%3D%2713%27%20rx%3D%276.5%27%20ry%3D%279.5%27%20transform%3D%27rotate%2835%2013%2013%29%27/%3E%3Cpath%20d%3D%27M13%204%20Q11%2013%2013%2022%27%20transform%3D%27rotate%2835%2013%2013%29%27/%3E%3Cellipse%20cx%3D%2734%27%20cy%3D%2734%27%20rx%3D%276.5%27%20ry%3D%279.5%27%20transform%3D%27rotate%28-22%2034%2034%29%27/%3E%3Cpath%20d%3D%27M34%2025%20Q32%2034%2034%2043%27%20transform%3D%27rotate%28-22%2034%2034%29%27/%3E%3C/g%3E%3C/svg%3E"), linear-gradient(135deg, #3b2417 0%, #5a3620 45%, #4e342e 100%);
    background-size: 23mm 23mm, cover;
    border-radius: 0 0 3mm 3mm;
    color: #f7ecdd; font-family: 'Helvetica Neue', Arial, sans-serif;
    display: flex; padding: 6mm; gap: 5mm;
}
.hqr-info { flex: 1 1 auto; display: flex; flex-direction: column; min-width: 0; }
.hqr-role { font-size: 7pt; letter-spacing: 2pt; text-transform: uppercase; color: #c9a06f; }
.hqr-name {
    font-size: 20pt; font-weight: 800; line-height: 1.1; color: #fff; margin: 2mm 0 auto;
    word-break: break-word; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.hqr-field { display: flex; flex-direction: column; margin-top: 3mm; }
.hqr-label { font-size: 6pt; letter-spacing: 1pt; text-transform: uppercase; color: #b89066; }
.hqr-value { font-size: 12pt; font-weight: 700; color: #f7ecdd; line-height: 1.1; }
.hqr-hid { color: #f0c98a; }
.hqr-qrbox { flex: 0 0 auto; flex-shrink: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.hqr-qr { width: 36mm; height: 36mm; background: #fff; padding: 2mm; border-radius: 2mm; box-sizing: border-box; object-fit: contain; display: block; }
.hqr-qrcap { margin-top: 2mm; font-size: 7pt; letter-spacing: 0.4pt; color: #e6c79a; font-weight: 600; }

html:
{% set _pp = 4 %}
{% set logo = "/assets/upande_coffee/images/endebess_logo.png" %}
<div class="hqr-wrap">
{%- for row in doc.labels %}
    {%- if loop.index0 % _pp == 0 %}<div class="hqr-page">{% endif %}
        <div class="hqr-card">
            <div class="hqr-top">
                {% if logo %}<img class="hqr-logo" src="{{ logo }}">{% else %}<div class="hqr-estate">Endebess Coffee Estate</div>{% endif %}
            </div>
            <div class="hqr-body">
                <div class="hqr-info">
                    <div class="hqr-role">Coffee Harvester</div>
                    <div class="hqr-name">{{ row.employee_name or "&mdash;" }}</div>
                    <div class="hqr-field"><span class="hqr-label">Employee&nbsp;No</span><span class="hqr-value">{{ row.employee_number or "&mdash;" }}</span></div>
                    <div class="hqr-field"><span class="hqr-label">Harvester&nbsp;ID</span><span class="hqr-value hqr-hid">{{ row.harvester_id }}</span></div>
                </div>
                <div class="hqr-qrbox">
                    {% if row.qr_code_image %}<img class="hqr-qr" src="{{ row.qr_code_image }}">{% endif %}
                    <div class="hqr-qrcap">{{ row.harvester_id }}</div>
                </div>
            </div>
        </div>
    {%- if loop.index % _pp == 0 or loop.last %}</div>{% endif %}
{%- endfor %}
</div>
